-- muhaysini: a labelled «لا» is a NO — «مفروشة: لا» was served as furnished = yes (facts test 2026-10-24).
--
-- The shared prose reader (scrapers/common/normalize.py amenities_from_text) looked for a negator only BEFORE a
-- token, so a labelled answer read YES: «- مفروشة: لا -», «**مفروش:** لا», «مؤثثة: غير مؤثثة», «المفروشات: غير
-- مفروش». muhaysini's generated «أبرز ملامح العقار» list prints exactly that. The reader is fixed in PR 8611
-- (a label's value is the answer: a negator → no, a restatement → that restatement, «غير محدد» / «لا توجد
-- تفاصيل» → unknown), pinned by scripts/verify-labelled-no-is-not-a-yes.ts. Rendered pages 15558, 29186 and
-- 17681 print «مفروشة: لا» / «**مفروش:** لا» / «مؤثثة: غير مؤثثة» while all three are served furnished = yes.
--
-- Repair = the old and the fixed reader replayed over every stored muhaysini row, built the way the scraper builds
-- it (description → structured furnished = true → utility / feature chips). A row changes only where its stored
-- value is the old reader's answer (or a stored yes the ad's own label says no to) and the fixed reader differs:
--   residential air_conditioner   true -> null      1
--   residential furnished         null -> false   334
--   residential furnished         true -> false  1537
--   residential furnished         true -> null     35
--   residential kitchen           true -> null      2
--   residential parking           true -> null      4
--   commercial  furnished         null -> false    13
--   commercial  furnished         true -> false    70
--   commercial  furnished         true -> null      1
-- A NULL here means the ad answered nothing («مواقف: غير محدد», «المطبخ: لا توجد تفاصيل») or contradicts itself,
-- and an upsert that drops None would never clear the old yes, so this half is repaired here. The served index
-- follows through listing_extra_attrs_mv (:20) and the hourly sync's «furnished is distinct from» limb (:22).

create or replace function public.mon_detect_muhaysini_labelled_no_read_as_furnished()
returns integer
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  n        int := 0;
  live     text[] := '{}';
  v_seen   bigint;
  v_bad    bigint;
  v_sample jsonb;
  -- «مفروشة: لا», «**مفروش:** لا», «مؤثثة: لا يوجد» — a furnished LABEL answered with a negator on the same line.
  -- «لا توجد تفاصيل / معلومات / بيانات» is no answer, so it is not counted.
  re_label constant text := '(مفروش|مؤثث)[ء-ي]{0,4}[ \t*]*[:：][ \t*]*';
  re_no    constant text := '(مفروش|مؤثث)[ء-ي]{0,4}[ \t*]*[:：][ \t*]*(لا(?![ \t]*[يت]وجد[ \t]+(تفاصيل|معلومات|بيانات))|لايوجد|لاتوجد|بدون)([^ء-ي]|$)';
begin
  with t as (
    select 'muhaysini_residential_listings' tbl, id, furnished, coalesce(description, '') d, additional_info ai
      from public.muhaysini_residential_listings where active
    union all
    select 'muhaysini_commercial_listings', id, furnished, coalesce(description, ''), additional_info
      from public.muhaysini_commercial_listings where active)
  select count(*) filter (where d ~ re_label),
         count(*) filter (where furnished and d ~ re_no and coalesce(ai->>'source_furnished_raw', '') <> 'true'),
         jsonb_agg(jsonb_build_object('t', tbl, 'id', id))
           filter (where furnished and d ~ re_no and coalesce(ai->>'source_furnished_raw', '') <> 'true')
    into v_seen, v_bad, v_sample
    from t;

  -- BLINDNESS GUARD: no active muhaysini ad labels its furnishing, so a 0 below proves nothing.
  if v_seen = 0 then
    live := live || 'muhaysini_labelled_no_read_as_furnished:BLIND'::text;
    n := n + public.mon_raise('P2', 'muhaysini_labelled_no_read_as_furnished', 'muhaysini',
      'muhaysini_labelled_no_read_as_furnished:BLIND',
      jsonb_build_object('blind', true,
        'why', 'No active muhaysini ad carries a «مفروشة: …» label, so a labelled no served as yes cannot be seen.',
        'action', 'Check the muhaysini description is still stored.'));
  elsif v_bad > 0 then
    live := live || 'muhaysini_labelled_no_read_as_furnished:yes_served'::text;
    n := n + public.mon_raise('P1', 'muhaysini_labelled_no_read_as_furnished', 'muhaysini',
      'muhaysini_labelled_no_read_as_furnished:yes_served',
      jsonb_build_object('rows', v_bad, 'labelled', v_seen,
        'sample', (select jsonb_agg(x) from (select x from jsonb_array_elements(v_sample) x limit 10) z),
        'why', 'The ad''s own label says «مفروشة: لا» yet furnished = yes is stored, so a customer asking for furnished gets it.',
        'action', 'normalize._amenities_in_clause must read a label''s value (_LABEL_RE / _LABEL_NO_RE); check the muhaysini crawl ran the fixed reader, then replay old vs new and repair.'));
  end if;

  perform public.mon_resolve_stale_keys('muhaysini_labelled_no_read_as_furnished', live);
  return n;
end
$function$;

-- Roster entry in the same change (AGENTS.md): a detector nothing reaches is decoration.
do $$
declare src text; out_def text;
begin
  src := pg_get_functiondef('public.mon_run_all_detectors()'::regprocedure);
  if position('mon_detect_muhaysini_labelled_no_read_as_furnished' in src) > 0 then
    raise notice 'mon_detect_muhaysini_labelled_no_read_as_furnished already on the roster';
    return;
  end if;
  out_def := replace(src,
    E'    ''mon_detect_district_name_read_as_balcony'',',
    E'    ''mon_detect_district_name_read_as_balcony'',\n    ''mon_detect_muhaysini_labelled_no_read_as_furnished'',');
  if out_def = src then
    raise exception 'roster anchor not found, refusing to guess where the entry belongs';
  end if;
  execute out_def;
end $$;

-- The detector must SEE the rows before the repair (a detector that reads 0 here is blind).
do $c$
declare k int;
begin
  perform public.mon_detect_muhaysini_labelled_no_read_as_furnished();
  select count(*) into k from public.alert_event
   where kind = 'muhaysini_labelled_no_read_as_furnished' and resolved_at is null
     and dedup_key = 'muhaysini_labelled_no_read_as_furnished:yes_served';
  if k = 0 then raise exception 'detector raised nothing while labelled-no furnished rows exist'; end if;
end $c$;

